/**
 * HunkStager provides granular control over git staging at the hunk level.
 * Allows developers to accept, reject, or preview individual diff blocks.
 */
export class HunkStager {
  private workspace: string;

  constructor(workspace: string) {
    this.workspace = path.resolve(workspace);
  }

  public getUnstagedDiff(filePath?: string): string {
    try {
      const args = ["diff"];
      if (filePath) {
        args.push("--", filePath);
      }
      return execFileSync("git", [...trustedGitArgs(this.workspace), ...args], {
        cwd: this.workspace,
        encoding: "utf-8",
        stdio: ["ignore", "pipe", "ignore"],
      });
    } catch {
      return "";
    }
  }

  public getStagedDiff(): string {
    try {
      return execFileSync("git", [...trustedGitArgs(this.workspace), "diff", "--cached"], {
        cwd: this.workspace,
        encoding: "utf-8",
        stdio: ["ignore", "pipe", "ignore"],
      });
    } catch {
      return "";
    }
  }

  public getParsedUnstagedDiff(filePath?: string): DiffFile[] {
    const raw = this.getUnstagedDiff(filePath);
    return parseDiffHunks(raw);
  }

  /**
   * Applies an individual hunk to the git index (staging it).
   */
  public stageHunk(file: DiffFile, hunk: DiffHunk): { success: boolean; error?: string } {
    const patch = buildSingleHunkPatch(file, hunk);
    try {
      execFileSync("git", [...trustedGitArgs(this.workspace), "apply", "--cached", "--unidiff-zero", "-"], {
        cwd: this.workspace,
        input: patch,
        encoding: "utf-8",
        stdio: ["pipe", "pipe", "pipe"],
      });
      hunk.accepted = true;
      return { success: true };
    } catch (err: any) {
      // Fallback: try standard git apply --cached without unidiff-zero
      try {
        execFileSync("git", [...trustedGitArgs(this.workspace), "apply", "--cached", "-"], {
          cwd: this.workspace,
          input: patch,
          encoding: "utf-8",
          stdio: ["pipe", "pipe", "pipe"],
        });
        hunk.accepted = true;
        return { success: true };
      } catch (fallbackErr: any) {
        return {
          success: false,
          error: fallbackErr.stderr || fallbackErr.message,
        };
      }
    }
  }

  /**
   * Reverts an individual hunk in the working tree (discarding changes in that block).
   */
  public discardHunk(file: DiffFile, hunk: DiffHunk): { success: boolean; error?: string } {
    const patch = buildSingleHunkPatch(file, hunk);
    try {
      execFileSync("git", [...trustedGitArgs(this.workspace), "apply", "--reverse", "--unidiff-zero", "-"], {
        cwd: this.workspace,
        input: patch,
        encoding: "utf-8",
        stdio: ["pipe", "pipe", "pipe"],
      });
      hunk.accepted = false;
      return { success: true };
    } catch (err: any) {
      try {
        execFileSync("git", [...trustedGitArgs(this.workspace), "apply", "--reverse", "-"], {
          cwd: this.workspace,
          input: patch,
          encoding: "utf-8",
          stdio: ["pipe", "pipe", "pipe"],
        });
        hunk.accepted = false;
        return { success: true };
      } catch (fallbackErr: any) {
        return {
          success: false,
          error: fallbackErr.stderr || fallbackErr.message,
        };
      }
    }
  }

  /**
   * Stages all pending modifications in a file.
   */
  public stageFile(filePath: string): boolean {
    try {
      execFileSync("git", [...trustedGitArgs(this.workspace), "add", filePath], { cwd: this.workspace });
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Unstages all staged changes for a file or the entire repository.
   */
  public unstage(filePath?: string): boolean {
    try {
      const args = ["reset", "HEAD"];
      if (filePath) {
        args.push("--", filePath);
      }
      execFileSync("git", [...trustedGitArgs(this.workspace), ...args], { cwd: this.workspace, stdio: "ignore" });
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Formats a summary of all unstaged and staged files.
   */
  public getStatusSummary(): { stagedCount: number; unstagedHunkCount: number; files: DiffFile[] } {
    const files = this.getParsedUnstagedDiff();
    const unstagedHunkCount = files.reduce((acc, f) => acc + f.hunks.length, 0);
    let stagedCount = 0;
    try {
      const stagedOut = execFileSync("git", [...trustedGitArgs(this.workspace), "diff", "--cached", "--name-only"], {
        cwd: this.workspace,
        encoding: "utf-8",
        stdio: ["ignore", "pipe", "ignore"],
      }).trim();
      stagedCount = stagedOut ? stagedOut.split("\n").filter(Boolean).length : 0;
    } catch {}

    return {
      stagedCount,
      unstagedHunkCount,
      files,
    };
  }
}

